declarations.code:
template <class I>

concept incrementable =

    std::regular<I> &&

    std::weakly_incrementable<I> &&

    requires(I i) {
        { i++ } -> std::same_as<I>;
    };

examples.code:
#include <iterator>
#include <functional>
#include <cassert>
#include <iostream>

int main() {
    static_assert(std::incrementable<int *>);
    int values[]{3, 7};
    int *position = values;
    assert(*position == 3);
    ++position;
    assert(*position == 7);
    std::cout << "Checks passed\n";
}
